const body = $input.item.json.body;
// Accepts either the manual test shape {showroomUuid} or the native
// VNTANA showroom.asset.added event shape {showroom: {uuid}}.
const showroomUuid = (body.showroomUuid || (body.showroom && body.showroom.uuid) || '').trim();
if (!showroomUuid || !/^[0-9a-f-]{36}$/i.test(showroomUuid)) {
  throw new Error('Missing or invalid showroom UUID in request body');
}
return [{ json: { showroomUuid } }];

const resp = $input.item.json;
if (!resp.success || !resp.response) {
  throw new Error(`Failed to fetch showroom: ${JSON.stringify(resp.errors)}`);
}

const showroom = resp.response;
const products = showroom.products || [];
if (!products.length) throw new Error('Showroom has no products to organize');

// --- Rules the structured path requires every asset to satisfy ---

// Rule 1: every asset must have a non-empty "Style" attribute (this is the group title).
const missingStyle = products.filter(p => !((p.attributes || {}).Style || '').trim());
if (missingStyle.length) {
  throw new Error(
    `Missing "Style" attribute on ${missingStyle.length} asset(s): ` +
    missingStyle.map(p => `${p.name} (${p.uuid})`).join(', ') +
    '. Add a Style attribute to every asset in the showroom before running the structured path.'
  );
}

// Rule 2: asset name must follow "<style>_<color>.<ext>" so a color code can be derived.
function colorCode(p) {
  const name = p.name || '';
  const noExt = name.replace(/\.[^.]+$/, '');
  const idx = noExt.indexOf('_');
  return idx === -1 ? null : noExt.slice(idx + 1);
}
const badNaming = products.filter(p => colorCode(p) === null);
if (badNaming.length) {
  throw new Error(
    `Asset name(s) missing the "<style>_<color>.ext" naming pattern needed to derive a color code: ` +
    badNaming.map(p => `${p.name} (${p.uuid})`).join(', ')
  );
}

function styleKey(p) {
  return (p.attributes || {}).Style.trim();
}

const groupMap = new Map();
products.forEach(p => {
  const title = styleKey(p);
  if (!groupMap.has(title)) groupMap.set(title, []);
  groupMap.get(title).push(p);
});

// Rule 3: no two assets in the same style group may share a color code (ambiguous order).
groupMap.forEach((items, title) => {
  const seen = new Map();
  items.forEach(p => {
    const c = colorCode(p);
    if (seen.has(c)) {
      throw new Error(
        `Duplicate color code "${c}" within group "${title}": ${seen.get(c)} and ${p.name} (${p.uuid}). ` +
        'Color codes must be unique within a style group.'
      );
    }
    seen.set(c, p.name);
  });
});

const titles = [...groupMap.keys()].sort((a, b) => a.localeCompare(b));

const apiGroups = titles.map(title => {
  const sorted = [...groupMap.get(title)].sort((a, b) => colorCode(a).localeCompare(colorCode(b)));
  return {
    title,
    dividers: ['TOP'],
    visible: true,
    productsInfo: sorted.map((p, i) => ({ productUuid: p.uuid, visible: true, order: i + 1 })),
  };
});

const reportRows = [];
titles.forEach(title => {
  const sorted = [...groupMap.get(title)].sort((a, b) => colorCode(a).localeCompare(colorCode(b)));
  sorted.forEach((p, i) => reportRows.push({ uuid: p.uuid, name: p.name, group: title, order: i + 1 }));
});

return [{
  json: {
    uuid: showroom.uuid,
    name: showroom.name,
    productsUuids: products.map(p => p.uuid),
    apiGroups,
    reportRows,
    showroomName: showroom.name,
  }
}];

const updateResp = $input.item.json;
const built = $('Calculate Group Allocations').first().json;
if (!updateResp.success) {
  throw new Error(`Failed to update showroom: ${JSON.stringify(updateResp.errors)}`);
}

const csvLines = ['Asset UUID,Asset Name,Group,Order'];
built.reportRows.forEach(r => {
  const name = String(r.name || '').replace(/,/g, ' ');
  const group = String(r.group || '').replace(/,/g, ' ');
  csvLines.push(`${r.uuid},${name},${group},${r.order}`);
});

const csv = csvLines.join('\n');
const filename = `${built.showroomName.replace(/[^a-zA-Z0-9 _-]/g, '')} - Organized.csv`;

return [{ json: { csv, filename, showroomName: built.showroomName, count: built.reportRows.length } }];

const { csv, filename } = $input.item.json;
const base64 = Buffer.from(csv, 'utf8').toString('base64');
return [{
  json: $input.item.json,
  binary: {
    data: {
      data: base64,
      mimeType: 'text/csv',
      fileName: filename,
    }
  }
}];
